renderer.valueExpression:
var featureDate = $feature.EditDate;
var m = $feature.wait_minutes;
if (IsEmpty(featureDate)) { 
    return "Hide"; 
}
var localFeature = ToLocal(featureDate);
var fHour = Hour(localFeature);
var fMinute = Minute(localFeature);
var fTimeInt = (fHour * 100) + fMinute;
var startPeriod1 = Date(2026, 9, 24, 0, 0);
var endPeriod1 = Date(2026, 10, 2, 23, 59);
var startPeriod2 = Date(2026, 10, 3, 0, 0);
var endPeriod2 = Date(2026, 10, 3, 23, 59);
var isValidWindow = false;
if (localFeature >= startPeriod1 && localFeature <= endPeriod1) {
    if (fTimeInt >= 800 && fTimeInt < 1700) {
        isValidWindow = true;
    }
} 
else if (localFeature >= startPeriod2 && localFeature <= endPeriod2) {
    if (fTimeInt >= 700 && fTimeInt < 2000) {
        isValidWindow = true;
    }
}
if (isValidWindow) {
    if (IsEmpty(m) || m < 0) { 
        return "No wait time reported"; 
    }

    return When(
        m <= 15, "< 15 min",
        m <= 30, "16-30 min",
        m <= 60, "31-60 min",
        m > 60, "61 + min",
        "No wait time reported"
    );
}

return "Hide";

expressionInfos.expression:
if ($feature.days == 11) {
    return TextFormatting.NewLine + "Open October 24 to November 2" + TextFormatting.NewLine + "8 a.m. to 5 p.m." + TextFormatting.NewLine;
}
else

return TextFormatting.NewLine + "Open October 31 to November 2" + TextFormatting.NewLine + "8 a.m. to 5 p.m." + TextFormatting.NewLine;

var waitLayerName = "Vote Center Wait Time";
var waitTimeLayer = FeatureSetByName($map, waitLayerName, ["wait_minutes", "EditDate"], false);
var bufferedPoint = Buffer($feature, 100, 'meters');
var featuresMatch = Intersects(waitTimeLayer, bufferedPoint);
var latestFeature = First(OrderBy(featuresMatch, 'EditDate DESC'));

if (latestFeature != null) {
    
    var m = latestFeature.wait_minutes;
    var t = latestFeature.EditDate;
    
    if (IsEmpty(t) || IsEmpty(m) || m < 0) {
        return "No wait time recorded";
    }
    var localFeature = ToLocal(t);
    var fYear = Year(localFeature);
    var fMonth = Month(localFeature);
    var fDay = Day(localFeature);
    var fHour = Hour(localFeature);
    var isValidTimeframe = false;

    if (fYear == 2026) {
        var isOctEarlyVoting = (fMonth == 9 && fDay >= 24 && fDay <= 31);
        var isNovEarlyVoting = (fMonth == 10 && fDay >= 1 && fDay <= 2);
        
        if ((isOctEarlyVoting || isNovEarlyVoting) && (fHour >= 8 && fHour < 17)) {
            isValidTimeframe = true;
        } 
        else if (fMonth == 10 && fDay == 3 && (fHour >= 7 && fHour < 20)) {
            isValidTimeframe = true;
        }
    }
    if (isValidTimeframe) {
        return "approx. " + m + " minutes";
    } else {
        return "No wait time recorded";
    }

} else {
    return "No wait data available for this location.";
}

